-- ---------------------------------------------------------------------------------------------
-- Hand-written: what Prisma cannot express. Each item is documented with `///` on its model.
-- ---------------------------------------------------------------------------------------------

-- Balances never go negative, and while the account is open what is held plus what is owed
-- never exceeds the limit: the last line of defence behind the row lock (ADR-0003).
ALTER TABLE "accounts"
  ADD CONSTRAINT "accounts_balances_non_negative" CHECK (
    "collateral_cents" >= 0 AND "credit_limit_cents" >= 0 AND "held_cents" >= 0 AND "posted_debt_cents" >= 0
  ),
  ADD CONSTRAINT "accounts_within_limit" CHECK (
    "status" = 'CLOSED' OR "held_cents" + "posted_debt_cents" <= "credit_limit_cents"
  );

-- One open (non-CLOSED) account per customer.
CREATE UNIQUE INDEX "accounts_one_open_per_customer" ON "accounts" ("customer_id") WHERE "status" <> 'CLOSED';

ALTER TABLE "collateral_deposits"
  ADD CONSTRAINT "collateral_deposits_amount_positive" CHECK ("amount_cents" > 0),
  ADD CONSTRAINT "collateral_deposits_ratio_range" CHECK ("limit_ratio_bps" > 0 AND "limit_ratio_bps" <= 10000);

ALTER TABLE "repayments"
  ADD CONSTRAINT "repayments_amount_positive" CHECK ("amount_cents" > 0),
  ADD CONSTRAINT "repayments_applied_range" CHECK ("applied_cents" >= 0 AND "applied_cents" <= "amount_cents");

ALTER TABLE "payouts"
  ADD CONSTRAINT "payouts_amount_positive" CHECK ("amount_cents" > 0);

ALTER TABLE "authorizations"
  ADD CONSTRAINT "authorizations_amount_positive" CHECK ("amount_cents" > 0),
  ADD CONSTRAINT "authorizations_captured_range" CHECK ("captured_cents" >= 0 AND "captured_cents" <= "amount_cents"),
  ADD CONSTRAINT "authorizations_decline_reason" CHECK (("status" = 'DECLINED') = ("decline_reason" IS NOT NULL));

ALTER TABLE "postings"
  ADD CONSTRAINT "postings_amount_non_zero" CHECK ("amount_cents" <> 0);

-- The ledger balances by construction: at commit, every journal entry has at least two
-- postings and they sum to zero. DEFERRABLE INITIALLY DEFERRED so an entry and its postings
-- are checked together, whatever the insert order inside the transaction (ADR-0002).
CREATE FUNCTION "assert_journal_entry_balanced"() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  checked_entry UUID;
  total NUMERIC;
  posting_count INTEGER;
BEGIN
  IF TG_TABLE_NAME = 'journal_entries' THEN
    checked_entry := NEW."id";
  ELSE
    checked_entry := NEW."entry_id";
  END IF;
  SELECT COALESCE(SUM("amount_cents"), 0), COUNT(*) INTO total, posting_count
    FROM "postings" WHERE "entry_id" = checked_entry;
  IF total <> 0 OR posting_count < 2 THEN
    RAISE EXCEPTION 'journal entry % is not balanced (sum %, postings %)', checked_entry, total, posting_count
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER "journal_entries_balanced"
  AFTER INSERT ON "journal_entries"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION "assert_journal_entry_balanced"();

CREATE CONSTRAINT TRIGGER "postings_balanced"
  AFTER INSERT ON "postings"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION "assert_journal_entry_balanced"();

-- The journal is append-only: a correction is a new entry, never an edit.
CREATE FUNCTION "reject_ledger_rewrite"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'the ledger is append-only (% on %)', TG_OP, TG_TABLE_NAME USING ERRCODE = '23514';
END;
$$;

CREATE TRIGGER "journal_entries_append_only"
  BEFORE UPDATE OR DELETE ON "journal_entries"
  FOR EACH ROW EXECUTE FUNCTION "reject_ledger_rewrite"();

CREATE TRIGGER "postings_append_only"
  BEFORE UPDATE OR DELETE ON "postings"
  FOR EACH ROW EXECUTE FUNCTION "reject_ledger_rewrite"();
